import 'package:flutter_test/flutter_test.dart';
import 'package:mad_flutter_practicum/data/data.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import 'mocks/datasource.mocks.dart';

void main() {
  test('probe: which future completes first (cache vs network)', () async {
    final MockRestDatasource rest = MockRestDatasource();
    final MockDbDatasource db = MockDbDatasource();

    when(rest.getNewsList()).thenAnswer((_) async {
      await Future<void>.delayed(Duration.zero);
      return [NewsModel(title: 'fresh', link: 'fresh', date: DateTime.now())];
    });
    when(db.getNewsList()).thenAnswer((_) async {
      await Future<void>.delayed(Duration.zero);
      return [NewsModel(title: 'cached', link: 'cached', date: DateTime.now())];
    });

    final NewsRepository repository = NewsRepositoryImpl(rest, db);

    final List<String> order = <String>[];

    final Future<void> cacheOnly = repository.loadNewsFeed(NewsFeedFilter.all).then((v) => order.add('cache:${v.first.title}'));
    final Future<void> fresh = repository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)).then((v) => order.add('fresh:${v.first.title}'));

    await Future.wait([cacheOnly, fresh]);

    // ignore: avoid_print
    print('ORDER => $order');
  });
}

