{"content": "import 'package:flutter_test/flutter_test.dart';
import 'package:intl/date_symbol_data_local.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';
import 'package:provider/provider.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

Future<void> main() async {
  await initializeDateFormatting(AppConstants.ruLocale, null);

  group('NewsListPage', () {
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    final cachedNewsItems = [
      NewsModel(title: 'Из кэша 1', link: 'https://example.com/cached/1', date: DateTime.now()),
      NewsModel(title: 'Из кэша 2', link: 'https://example.com/cached/2', date: DateTime.now()),
    ];

    final freshNewsItems = [
      NewsModel(title: 'Заголовок 1', link: 'https://example.com/1', date: DateTime.now()),
      NewsModel(title: 'Заголовок 2', link: 'https://example.com/2', date: DateTime.now()),
    ];

    setUp(() {
      // NewsFeedFilter не имеет value-равенства, поэтому различаем режим по forceRefresh
      // внутри одного стаба. Сеть отвечает с задержкой, кэш — сразу: так же, как в БД.
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((Invocation invocation) async {
        final NewsFeedFilter filter = invocation.positionalArguments.single as NewsFeedFilter;

        await Future<void>.delayed(filter.forceRefresh ? const Duration(milliseconds: 50) : Duration.zero);

        return filter.forceRefresh ? freshNewsItems : cachedNewsItems;
      });
      when(mockNewsRepository.saveNewsList(any)).thenAnswer((_) async {});
    });

    testWidgets('should show cached news first and then replace it with fresh news', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: [
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const NewsListPage(),
        ),
      );

      // Список пуст, пока не пришёл кэш.
      expect(find.text('Из кэша 1'), findsNothing);
      expect(find.text('Заголовок 1'), findsNothing);

      // Кэш показывается сразу, без ожидания сети.
      await tester.pump();

      expect(find.text('Из кэша 1'), findsOneWidget);
      expect(find.text('Из кэша 2'), findsOneWidget);
      expect(find.text('Заголовок 1'), findsNothing);

      // По приходу сети список обновляется.
      await tester.pump(const Duration(milliseconds: 100));
      await tester.pumpAndSettle();

      expect(find.text('Заголовок 1'), findsOneWidget);
      expect(find.text('Заголовок 2'), findsOneWidget);
      expect(find.text('Из кэша 1'), findsNothing);

      final List<NewsFeedFilter> requests = verify(mockNewsRepository.loadNewsFeed(captureAny)).captured.cast<NewsFeedFilter>();

      expect(requests.where((NewsFeedFilter filter) => !filter.forceRefresh), hasLength(1));
      expect(requests.where((NewsFeedFilter filter) => filter.forceRefresh), hasLength(1));
    });
  });
}
